    /**
     * Method to retrieve the User via UserFetchOneSummary
     * @param 	summary UserFetchOneSummary 
     * @return 	UserFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public User getUser( UserFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "UserFetchOneSummary arg cannot be null" );
    	
    	User entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a User
        	// --------------------------------------
        	CompletableFuture<User> futureEntity = queryGateway.query(new FindUserQuery( new LoadUserFilter( summary.getUserId() ) ), ResponseTypes.instanceOf(User.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate User with id " + summary.getUserId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


